"""Sourced1840–1859 context, institutions and navigation; no invented fronts."""
import pathlib,json,copy,re
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'public/data';PREFIX='extension-1840-'
def prepare(context,history):
 c,h=copy.deepcopy((context,history));c['events']=[e for e in c['events'] if not e['id'].startswith(PREFIX)];h['records']=[e for e in h['records'] if not e['id'].startswith(PREFIX)];h['relations']=[e for e in h['relations'] if not e['id'].startswith(PREFIX)]
 def add(key,title,kind,a,b,countries,text,url,section='history'):
  assert '1840-01-01'<=a<b<='1860-01-01'
  title=re.sub(r'(?<=[A-Za-záéíóúñÁÉÍÓÚÑ])(?=[0-9])|(?<=[0-9])(?=[A-Za-záéíóúñÁÉÍÓÚÑ])',' ',title)
  text=re.sub(r'(?<=[A-Za-záéíóúñÁÉÍÓÚÑ])(?=[0-9])|(?<=[0-9])(?=[A-Za-záéíóúñÁÉÍÓÚÑ])',' ',text)
  note='Observación documental. No proporciona una geometría de frentes ni una lista exhaustiva de beligerantes. Los límites de cobertura no son fechas de inicio o paz.'
  bounds=dict(precision=9 if a.endswith('-01-01') else 11,startIsCoverageBoundary=a.endswith('-01-01'),endIsCoverageBoundary=b.endswith('-01-01'))
  c['events'].append(dict(id=PREFIX+key,title=title,type=kind,start=a,end=b,countries=[{'QING':'QNG'}.get(k,k) for k in countries],text=text,source=url,sourceLabel='Fuente institucional · investigación1840–1859',note=note,**bounds))
  h['records'].append(dict(id=PREFIX+'record-'+key,keys=countries,section=section,title=title,start=a,end=b,text=text,source=url,sourceLabel='Fuente institucional · investigación1840–1859',note=note,**bounds))
 add('france-july','Francia · Monarquía de Julio','transition','1840-01-01','1848-02-24',['FRA'],'Luis Felipe de Orleans gobierna antes de la revolución de febrero de1848. La denominación borbónica del contorno de fuente no identifica correctamente este régimen.','https://www.elysee.fr/louis-napoleon-bonaparte','institutions')
 add('france-republic','Francia · Segunda República','transition','1848-02-24','1852-12-02',['FRA'],'El Gobierno provisional y el Poder Ejecutivo de Cavaignac preceden a la presidencia constitucional. Luis Napoleón es elegido el10de diciembre y jura el20de diciembre de1848. El golpe de1851 y el Imperio de1852 son cambios distintos.','https://www.elysee.fr/louis-napoleon-bonaparte','institutions')
 add('france-empire','Francia · Segundo Imperio','transition','1852-12-02','1860-01-01',['FRA'],'La proclamación imperial transforma el régimen desde diciembre de1852; el mismo protagonista conserva fases de cargo diferentes. El corte1860 delimita esta observación, no el fin del Imperio.','https://www.elysee.fr/louis-napoleon-bonaparte','institutions')
 add('spain-regencies','España · fin de la regencia de María Cristina y transición','transition','1840-01-01','1841-05-10',['ESP'],'La renuncia de María Cristina en octubre de1840 abre un ministerio-regencia. La elección parlamentaria de Espartero en1841 se distingue de su influencia política en1840.','https://ocw.uc3m.es/pluginfile.php/7622/mod_page/content/25/T2-1-1-6_Regencia-Espartero.pdf','institutions')
 add('spain-espartero','España · regencia de Espartero','transition','1841-05-10','1844-01-01',['ESP'],'La regencia termina durante la crisis de1843, seguida de la mayoría de edad de Isabel II. El corte de este resumen es anual; no fecha un cese el1de enero de1844.','https://www.congreso.es/ca/cem/regespartero','institutions')
 add('spain-biennium','España · Bienio Progresista','transition','1854-01-01','1857-01-01',['ESP'],'La revolución de1854 abre un proceso constituyente y reformas como la desamortización de1855. La Constitución de1856 no llega a regir; esta observación anual no la presenta como constitución promulgada.','https://www.congreso.es/en/web/guest/cem/bieprog','institutions')
 add('brazil-majority','Brasil · fin de la regencia','transition','1840-01-01','1841-01-01',['BRA-EMPIRE'],'La mayoría anticipada de Pedro II se declara el23de julio de1840 y termina la regencia. No se confunde con la coronación posterior.','https://www.senado.leg.br/senado/hotsites/histsf/O-Senado-no-2o-Reinado.asp','institutions')
 add('german-revolution','Revoluciones de1848 y Asamblea de Fráncfort','transition','1848-01-01','1850-01-01',['HIST-Q151624','PRUSSIA','HIST-Q154195','AUSTRIAN-EMPIRE'],'Las revoluciones y la Asamblea de Fráncfort no convierten la Confederación Germánica en un Estado nacional unificado. Prusia sigue siendo una monarquía separada donde la fuente permite representarla.','https://www.dhm.de/lemo/kapitel/vormaerz-und-revolution/revolution-1848','institutions')
 add('crimea','Guerra de Crimea','conflict','1853-01-01','1856-03-31',['RUE','OTT'],'La guerra enfrenta a Rusia con el Imperio otomano y potencias aliadas. Las operaciones en Crimea son una parte del conflicto; el tratado de París se firma el30de marzo de1856. No se inventa un frente a partir de esta ficha.','https://www.nam.ac.uk/explore/crimean-war','defense')
 add('crimea-west','Guerra de Crimea · intervención franco-británica','conflict','1854-01-01','1856-03-31',['GBR','FRA'],'Francia y el Reino Unido entran en guerra en1854. Esta observación anual no atribuye su beligerancia al inicio ruso-otomano de1853 ni convierte el1de enero en una declaración de guerra.','https://www.thegazette.co.uk/all-notices/content/100497','defense')
 add('crimea-sardinia','Guerra de Crimea · participación sarda','conflict','1855-01-01','1856-03-31',['SAR'],'El Reino de Cerdeña se suma a la alianza en1855 y envía un cuerpo expedicionario. La ventana anual no atribuye su participación a1853 ni a1854.','https://www.carabinieri.it/arma/arma-all%27estero/proiezione-internazionale/vol-i-1855---1935/1855---1856/in-crimea','defense')
 add('taiping','Guerra civil Taiping · fase1851–1859','conflict','1851-01-01','1860-01-01',['QING','HIST-Q3486676'],'El Reino Celestial Taiping disputa el poder a la dinastía Qing, con instituciones y autoridades propias. El corte de1859 delimita esta ampliación; la guerra continúa hasta1864. No se deducen frentes anuales de esta síntesis documental.','https://www.britishmuseum.org/sites/default/files/2023-09/Chinas_hidden_century_large_print_guide.pdf','defense')
 add('opium-one','Primera guerra del Opio · fase1840–1842','conflict','1840-01-01','1843-01-01',['QING','GBR','IND'],'Conflicto iniciado en1839, observado aquí desde1840. Los intereses comerciales británicos y la resistencia Qing son parte del contexto; el recorte temporal no mueve el inicio de la guerra a1840.','https://www.nam.ac.uk/explore/first-china-war-1839-1842','defense')
 add('mexico-war','Guerra entre México y Estados Unidos','conflict','1846-01-01','1848-05-31',['USA','MEX'],'La guerra y el tratado de Guadalupe Hidalgo transforman la frontera. Firma del tratado2/2/1848 y ratificaciones son fases distintas; el resumen no convierte cada reclamación territorial en control efectivo.','https://www.archives.gov/milestone-documents/treaty-of-guadalupe-hidalgo','defense')
 add('oregon','Acuerdo sobre el territorio de Oregón','transition','1846-01-01','1847-01-01',['USA','GBR','CAN'],'El acuerdo angloestadounidense lleva la frontera al paralelo49, con la excepción de la isla de Vancouver. La síntesis anual del inventario no es un levantamiento diario de la frontera.','https://history.state.gov/milestones/1830-1860/oregon-territory','relations')
 add('india-rebellion','India · rebelión y cambio de gobierno','conflict','1857-01-01','1860-01-01',['IND','GBR'],'La rebelión de1857 precede al traspaso del gobierno de la Compañía a la Corona en1858. Victoria todavía no ostenta el título imperial indio de1877. No se trazan frentes regionales no documentados.','https://www.royal.uk/encyclopedia/victoria-r-1837-1901','institutions')
 add('hawaii-succession','Hawái · sucesión de1854','transition','1854-12-15','1855-01-01',['HAW-KINGDOM'],'La proclamación contemporánea del15de diciembre anuncia la muerte de Kamehameha III y la sucesión de Kamehameha IV; se distingue de ceremonias posteriores.','https://digitalarchives.hawaii.gov/item/ark%3A70111/51NQ','institutions')
 for ident,title,fromkey,fromyear,tokey,toyear,date,url in [
  ('france1848','De la monarquía a la República','FRA',1847,'FRA',1848,'1848-02-24','https://www.elysee.fr/louis-napoleon-bonaparte'),
  ('france1852','De la República al Segundo Imperio','FRA',1851,'FRA',1852,'1852-12-02','https://www.elysee.fr/louis-napoleon-bonaparte'),
  ('brazil1840','De la regencia al gobierno personal','BRA-EMPIRE',1840,'BRA-EMPIRE',1841,'1840-07-23','https://www.senado.leg.br/senado/hotsites/histsf/O-Senado-no-2o-Reinado.asp'),
  ('india1858','De la Compañía al gobierno de la Corona','IND',1857,'IND',1858,'1858-01-01','https://www.royal.uk/encyclopedia/victoria-r-1837-1901')]:
  names={'FRA':'Francia','BRA-EMPIRE':'Imperio del Brasil','IND':'India británica'}
  h['relations'].append(dict(id=PREFIX+ident,label=title,type='regime-transition',date=date,**{'from':dict(key=fromkey,name=names[fromkey],year=fromyear),'to':dict(key=tokey,name=names[tokey],year=toyear)},source=url,sourceLabel='Fuente institucional · investigación1840–1859',note='Navegación entre años de referencia; el día del enlace indio es límite anual de cobertura, no la fecha del acto de transferencia.'))
 c['startYear']=1840;h['coverageStart']='1840-01-01'
 return c,h
if __name__=='__main__':
 old=[json.loads((OUT/f).read_text(encoding='utf8')) for f in ['historical-context.json','country-history.json']];new=prepare(*old);assert prepare(*new)==new
 for before,after,fields in [(old[0],new[0],['events']),(old[1],new[1],['records','relations'])]:
  for field in fields:
   ids={r['id']:r for r in after[field]}
   for r in before[field]:
    if not r['id'].startswith(PREFIX):assert ids[r['id']]==r
 for f,d in zip(['historical-context.json','country-history.json'],new):(OUT/f).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf8',newline='\n')
 print('Added17 sourced phases,17 institutional/history records and4 navigation relations')
